#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    /* Usage message when not enough arguments */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    /* Bad input: conversion failed or extra characters */
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Overflow detection – strtol returns LONG_MIN on overflow */
    if (a == LONG_MIN || b == LONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    /* Range check – absolute values must not exceed 1,000,000 */
    long abs_a = a < 0 ? -a : a;
    long abs_b = b < 0 ? -b : b;
    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Special case when both numbers are zero */
    if (a == 0 && b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    /* Compute GCD using Euclidean algorithm on absolute values */
    long x = abs_a;
    long y = abs_b;
    while (y != 0) {
        long r = x % y;
        x = y;
        y = r;
    }
    long gcd = x;

    /* Compute LCM = (|a| / gcd) * |b| */
    long lcm = (abs_a / gcd) * abs_b;

    printf("gcd=%ld lcm=%ld\n", gcd, lcm);
    return 0;
}
